def shortest_cover(log, needed):
    if not needed:
        return ''
    need = {}
    for c in needed:
        need[c] = need.get(c, 0) + 1
    missing = len(needed)
    start = 0
    best = (float('inf'), 0)
    for end, c in enumerate(log):
        if need.get(c, 0) > 0:
            missing -= 1
        need[c] = need.get(c, 0) - 1
        while missing == 0:
            if end - start + 1 < best[0]:
                best = (end - start + 1, start)
            left = log[start]
            need[left] += 1
            if need[left] > 0:
                missing += 1
            start += 1
    length, s = best
    return '' if length == float('inf') else log[s:s + length]

