function shortest_cover(log, needed) {
  if (!needed) return '';
  const need = new Map();
  for (const c of needed) need.set(c, (need.get(c) || 0) + 1);
  let missing = needed.length;
  let start = 0;
  let bestLen = Infinity;
  let bestStart = 0;
  for (let end = 0; end < log.length; end++) {
    const c = log[end];
    if ((need.get(c) || 0) > 0) missing--;
    need.set(c, (need.get(c) || 0) - 1);
    while (missing === 0) {
      if (end - start + 1 < bestLen) {
        bestLen = end - start + 1;
        bestStart = start;
      }
      const left = log[start];
      need.set(left, need.get(left) + 1);
      if (need.get(left) > 0) missing++;
      start++;
    }
  }
  return bestLen === Infinity ? '' : log.slice(bestStart, bestStart + bestLen);
}

